parameters.jsCode:
for (const item of items) {
  const buf = Buffer.from(item.json.imageBase64, 'base64');
  item.binary = { data: { data: buf.toString('base64'), mimeType: 'image/png', fileName: `${item.json.contentItemId}_${item.json.platform}.png` } };
}
return items;

const li = $items('Format LinkedIn Output')[0].json;
const ig = $items('Format IG Output')[0].json;
const x = $items('Format X Output')[0].json;
return [{ json: { contentItemId: li.contentItemId, linkedin: li.draftText, instagram: ig.draftText, instagramHashtags: ig.hashtags, xThread: x.draftText } }];

const body = items[0].json.body || items[0].json;
const result = body.reviewResult || {};
const data = result.data || {};
return [{ json: {
  contentItemId: body.metadata && body.metadata.contentItemId,
  status: result.response === 'approved' ? 'approved' : 'rejected',
  linkedin: data.linkedinDraft,
  instagram: data.instagramDraft,
  xThread: data.xThread
} }];
